// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"REST",0,1],[80,"A",0,1],[96,"A",0,1],[112,"A",0,1],[128,"A",0,1],[144,"A",0,1],[160,"A",0,1],[176,"REST",0,1],[208,"REST",0,1],[224,"A",0,1],[240,"A",0,1],[256,"A",0,1],[272,"A",0,1],[288,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"B",0,1],[32,"B",0,1],[48,"B",0,1],[64,"B",0,1],[80,"REST",0,1],[176,"BRIDGE",0,1],[192,"BRIDGE",0,1],[208,"RUN",0,1],[224,"REST",0,1],[288,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[80,"REST",0,1],[176,"REST",0,1],[208,"REST",0,1],[224,"HARMONY",0,1],[288,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- mysterybox --------------------------------------------------------------------------------
const track0 = {
  color: '#c9a7ff',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [72 + m.n] : [] },
  formula: ["Mb = \\Rev\\,\\Dly_{\\text{пинг-понг } 3/16}\\Big[T(f \\cdot 2^{-7/1200})_{L} + T(f \\cdot 2^{7/1200})_{R}\\Big],\\quad T = v\\big(e^{-t(0.9 + f/2000)}\\sin 2\\pi ft + 0.25e^{-9t}\\sin 2\\pi\\,6.27ft\\big) + 0.35\\,FM_{3.5}(2f)","\\text{октавой выше, широко: две копии на } \\pm 7\\ \\text{центов слева и справа}"],
  audio({ bpm }) {
    const sec = 60 / bpm, tone = (f, t, v) => v * Math.min(1, t / 0.0008) * (exp(-t * (0.9 + f / 2000)) * (sin(TAU * f * t) + 0.25 * exp(-9 * t) * sin(TAU * 6.27 * f * t)) + 0.35 * fm(2 * f, t, { ratio: 3.5, index: 1.2, decay: 2.6, idecay: 8 }))
    const L = poly(tone, { release: 0.6, life: 4 }), R = poly(tone, { release: 0.6, life: 4 }), fire = trigger()
    const pingL = delay({ time: sec * 0.75, feedback: 0.42, wet: 0.32 }), verb = reverb({ room: 0.9, damp: 0.3, wet: 0.36 })
    return x => {
      const m = leadAt(x)
      if (fire(m ? m.at : null)) { const f = hz(m.n + 12, C4), v = 0.8 + 0.15 * hash(floor(4 * x), 3); L.hit(f * 2 ** (-7 / 1200), v, m.d * sec + 0.5); R.hit(f * 2 ** (7 / 1200), v, m.d * sec + 0.5, 0.004) }
      const k = 0.306, l = k * L(), r = k * R()
      const [el, er] = pingL(l, r)
      return verb(el + 0.15 * er, er + 0.15 * el)
    }
  },
}

